// The user's final view of the MAGNETIC SCOOTER (2026-11-17), cut out of its white ground, for the scooter indicator: a comic speech bubble with the picture inside (src/render.js drawScooterHint). WebP with alpha, 216x256.
const SCOOTER_ART = { w: 216, h: 256, src: 'data:image/webp;base64,' };
if (typeof Image !== 'undefined') { SCOOTER_ART.img = new Image(); SCOOTER_ART.img.src = SCOOTER_ART.src; }      // (loaded at start-up: the bubble shows the picture from its first pop)
// the user's final view of the SPORT E-BIKE (2026-11-18), cut out the same way, for its indicator bubble
